INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (4, 'Carbonara da manuale', 5, 'Guanciale croccante, pasta al dente. La migliore di Roma.', CURRENT_DATE - 83, 1, 7);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (5, 'Serata perfetta', 5, 'Servizio attento senza essere invadente. Torneremo.', CURRENT_DATE - 39, 1, 8);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (6, 'Ottimo rapporto qualita prezzo', 5, 'Si mangia bene e si spende il giusto.', CURRENT_DATE - 102, 1, 9);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (7, 'Cacio e pepe cremosa', 5, 'Niente grumi, come si deve.', CURRENT_DATE - 167, 1, 10);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (8, 'Molto buono', 4, 'Tutto ottimo, il locale pero e piccolo e si sta stretti.', CURRENT_DATE - 13, 1, 11);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (9, 'Consigliato', 4, 'Cucina romana fatta bene, prezzi onesti.', CURRENT_DATE - 19, 1, 12);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (10, 'Buona cena', 4, 'Amatriciana centrata, dolci nella media.', CURRENT_DATE - 211, 1, 13);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (11, 'Ci torneremo', 4, 'Bene il cibo, un po lenta l attesa fra i piatti.', CURRENT_DATE - 138, 1, 14);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (12, 'Bene ma affollato', 4, 'Prenotate, senza tavolo non si entra.', CURRENT_DATE - 25, 1, 15);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (13, 'Nella media', 3, 'Piatti corretti ma niente di memorabile.', CURRENT_DATE - 94, 1, 16);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (14, 'Aspettative alte', 3, 'Me ne avevano parlato benissimo, mi aspettavo di piu.', CURRENT_DATE - 150, 1, 17);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (15, 'Serata storta', 2, 'Ordinazione sbagliata e conto arrivato dopo mezz ora.', CURRENT_DATE - 15, 1, 18);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (16, 'Pesce freschissimo', 5, 'Le vongole si sentivano di mare. Bravi.', CURRENT_DATE - 233, 2, 7);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (17, 'Crudo eccellente', 5, 'Gamberi rossi dolcissimi, vale il prezzo.', CURRENT_DATE - 130, 2, 8);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (18, 'Molto buono', 4, 'Fritto leggero, non unto per niente.', CURRENT_DATE - 55, 2, 9);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (19, 'Bene', 4, 'Tagliata cotta come richiesto, contorni scarsi.', CURRENT_DATE - 10, 2, 10);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (20, 'Discreto', 3, 'Buono ma caro per quello che offre.', CURRENT_DATE - 23, 2, 11);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (21, 'Serata tranquilla', 4, 'Locale silenzioso, si riesce a parlare.', CURRENT_DATE - 112, 2, 12);
