INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (101, 'La migliore del quartiere', 5, 'Cornicione alto e leggero, si digerisce benissimo. Coda fuori ma scorre veloce.', CURRENT_DATE - 6, 4, 25);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (102, 'Impasto da applausi', 5, 'Ventiquattr ore di lievitazione si sentono tutte. Prezzi onesti.', CURRENT_DATE - 21, 4, 26);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (103, 'Ottima pizza, locale caotico', 4, 'Si mangia benissimo ma il chiasso e tanto: non e il posto per parlare.', CURRENT_DATE - 34, 4, 12);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (104, 'Marinara perfetta', 4, 'Semplice e fatta come si deve. I crocche pero erano tiepidi.', CURRENT_DATE - 58, 4, 9);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (105, 'Serata sfortunata', 3, 'Quarantacinque minuti per due pizze e la diavola poco cotta sotto.', CURRENT_DATE - 12, 4, 17);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (106, 'Ci vado ogni settimana', 5, 'Rapporto qualita prezzo imbattibile, personale gentile.', CURRENT_DATE - 77, 4, 3);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (107, 'Cucina toscana vera', 5, 'La ribollita e quella della nonna. Vino della casa piu che dignitoso.', CURRENT_DATE - 9, 5, 27);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (108, 'Peposo notevole', 4, 'Carne che si scioglie. Porzioni generose, ambiente semplice.', CURRENT_DATE - 41, 5, 10);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (109, 'Bene la fiorentina', 4, 'Cottura al sangue rispettata, contorni migliorabili.', CURRENT_DATE - 96, 5, 14);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (110, 'Buono ma lento', 3, 'Piatti corretti, servizio molto lento in una sera piena.', CURRENT_DATE - 27, 5, 2);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (111, 'Pici memorabili', 5, 'Aglione dolce e pasta tirata a mano. Torneremo di sicuro.', CURRENT_DATE - 15, 5, 29);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (112, 'Pesce freschissimo', 5, 'Sashimi tagliato al momento, ramen con brodo denso al punto giusto.', CURRENT_DATE - 11, 6, 28);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (113, 'Buono e curato', 4, 'Sushi ben fatto, sala un po fredda. Servizio attento.', CURRENT_DATE - 36, 6, 11);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (114, 'Ramen consigliato', 4, 'Il tonkotsu vale il viaggio, il resto e nella media.', CURRENT_DATE - 63, 6, 16);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (115, 'Non ci torno', 2, 'Riso slegato e attesa lunghissima per i nigiri. Peccato.', CURRENT_DATE - 19, 6, 30);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (116, 'Discreto', 3, 'Niente di sbagliato, niente di memorabile. Prezzi alti.', CURRENT_DATE - 88, 6, 8);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (117, 'Finalmente vegano buono', 5, 'Il burger di ceci non sa di rinuncia. Dolce ottimo.', CURRENT_DATE - 8, 7, 25);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (118, 'Curry ben speziato', 4, 'Porzioni giuste, locale piccolo e accogliente.', CURRENT_DATE - 44, 7, 13);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (119, 'Leggero e saporito', 4, 'Si esce sazi senza pesantezza. Consigliato a pranzo.', CURRENT_DATE - 70, 7, 18);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (120, 'Carino ma caro', 3, 'Dieci euro per un insalata di farro sono tanti.', CURRENT_DATE - 23, 7, 26);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (121, 'Carne di livello', 5, 'Frollatura giusta e brace vera. La tagliata era perfetta.', CURRENT_DATE - 5, 8, 29);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (122, 'Grigliata abbondante', 5, 'In due non l abbiamo finita. Servizio cordiale.', CURRENT_DATE - 30, 8, 15);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (123, 'Buona brace', 4, 'Hamburger di chianina ottimo, patate un po unte.', CURRENT_DATE - 52, 8, 7);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (124, 'Bene', 4, 'Costata cotta bene, sala rumorosa nel fine settimana.', CURRENT_DATE - 17, 8, 30);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (125, 'Nella media', 3, 'Carne discreta ma il conto sale in fretta.', CURRENT_DATE - 101, 8, 3);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (126, 'Bel posto per leggere', 4, 'Tagliere generoso e silenzio. Peccato abbia chiuso.', CURRENT_DATE - 120, 9, 27);
INSERT INTO recensione (id, titolo, voto, testo, data, ristorante_id, user_id) VALUES (127, 'Simpatico ma essenziale', 3, 'Buon caffe, cucina limitata. Andava bene per un pranzo veloce.', CURRENT_DATE - 156, 9, 12);
